export { default as Status } from "./Status.vue";
export { default as StatusIndicator } from "./StatusIndicator.vue";
export { default as StatusLabel } from "./StatusLabel.vue";
export type * from "./types.ts";

@layer components {
  /* Status: a 6px dot in the brighter status color and a label. A colored label uses the darker text shade of the theme. */
  [data-slot="status"] {
    align-items: center;
    display: inline-flex;
    font-size: 0.75rem;
    gap: 0.375rem;
    line-height: 1rem;
    min-width: 0;
  }

  [data-slot="status"][data-size="md"] {
    font-size: 0.875rem;
    line-height: 1.25rem;
  }

  [data-slot="status-indicator"] {
    background: var(--vh-dimmed);
    border-radius: 9999px;
    flex: none;
    height: 0.375rem;
    position: relative;
    width: 0.375rem;
  }

  [data-slot="status"][data-tone="success"] [data-slot="status-indicator"] {
    background: var(--vh-success);
  }

  [data-slot="status"][data-tone="warning"] [data-slot="status-indicator"] {
    background: var(--vh-warning);
  }

  [data-slot="status"][data-tone="error"] [data-slot="status-indicator"] {
    background: var(--vh-error);
  }

  [data-slot="status"][data-tone="info"] [data-slot="status-indicator"] {
    background: var(--vh-info);
  }

  [data-slot="status"][data-colored][data-tone="success"] {
    color: var(--vh-text-success, var(--vh-success));
  }

  [data-slot="status"][data-colored][data-tone="warning"] {
    color: var(--vh-text-warning, var(--vh-warning));
  }

  [data-slot="status"][data-colored][data-tone="error"] {
    color: var(--vh-text-error, var(--vh-error));
  }

  [data-slot="status"][data-colored][data-tone="info"] {
    color: var(--vh-text-info, var(--vh-info));
  }

  [data-slot="status-label"] {
    min-width: 0;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
  }

  /* A live or pending status pulses, as the connection dot does. */
  [data-slot="status"][data-pulse] [data-slot="status-indicator"] {
    animation: status-pulse 1.5s ease-in-out infinite;
  }

  @keyframes status-pulse {
    50% {
      opacity: 0.35;
    }
  }

  @media (prefers-reduced-motion: reduce) {
    [data-slot="status"][data-pulse] [data-slot="status-indicator"] {
      animation: none;
    }
  }
}

export type StatusTone = "neutral" | "success" | "warning" | "error" | "info";
export type StatusSize = "sm" | "md";

export interface StatusProps {
  /** The color of the dot. */
  tone?: StatusTone;
  /** The text after the dot. Without it and without children, only the dot renders. */
  label?: string;
  size?: StatusSize;
  /** The label takes the tone's color too, when the label is the status itself, such as "Failed". */
  colored?: boolean;
  /** The dot pulses, for a live or pending status. */
  pulse?: boolean;
}

export interface StatusSlots {
  /** Replaces the default composition: put `StatusIndicator` and `StatusLabel` in it. */
  default?: () => unknown;
}
